const s = $json;
const SYSTEM = "Tu es un coach carrière tech français, direct, concret et encourageant.\nÀ partir des statistiques hebdomadaires de recherche d'emploi d'un candidat, produis un bilan utile.\nBase-toi uniquement sur les chiffres fournis. Donne des actions précises et réalisables cette semaine.\nRéponds UNIQUEMENT avec un objet JSON valide :\n{\n  \"headline\": \"Une phrase de bilan\",\n  \"wins\": [\"2 points positifs max\"],\n  \"actions\": [{\"action\": \"Action concrète\", \"why\": \"Pourquoi, en une phrase\"}],\n  \"skill_of_the_week\": {\"name\": \"Compétence à travailler\", \"why\": \"Pourquoi elle\", \"how\": \"Comment progresser en 3-5 h (ressource ou mini-projet)\"},\n  \"motivation\": \"Une phrase de motivation sincère, pas cliché\"\n}\nDonne exactement 3 actions.";
return [{
  json: {
    stats: s,
    llm_body: {
      temperature: 0.5,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: 'Statistiques de la semaine (JSON) :\n' + JSON.stringify(s, null, 2) },
      ],
    },
  },
}];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const parseLLM = (resp) => {
  if (resp?.error) throw new Error(resp.error.message || JSON.stringify(resp.error).slice(0, 300));
  const content = resp?.choices?.[0]?.message?.content;
  if (!content) throw new Error('Réponse vide du modèle IA');
  const clean = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
  return JSON.parse(clean);
};
// Telegram limite un message à 4096 caractères : on coupe proprement à la fin d'une ligne
const fit = (text, max = 3900) => {
  if (text.length <= max) return text;
  const cut = text.lastIndexOf('\n', max);
  return text.slice(0, cut > 0 ? cut : max) + '\n…';
};

const s = $('Préparer le coaching').first().json.stats;
const responseRate = s.total_applications ? Math.round((s.total_answers / s.total_applications) * 100) : 0;
const lines = [
  '📊 <b>Ton rapport de la semaine</b>',
  '',
  `📥 ${s.collected} offres collectées · 🤖 ${s.analysed} analysées (score moyen ${s.avg_score ?? '—'})`,
  `🎯 ${s.top_matches} pépites au-dessus de ton seuil`,
  `✍️ ${s.letters} lettres · 📨 ${s.applied} candidatures`,
  `🎤 ${s.interviews} entretiens · 🎉 ${s.offers} offres · ❌ ${s.rejections} refus`,
  `📈 Taux de réponse global : <b>${responseRate}%</b> (${s.total_answers}/${s.total_applications})`,
];
if (s.missing_skills?.length) {
  lines.push('', '🧩 <b>Compétences les plus demandées qui te manquent</b>');
  lines.push(...s.missing_skills.slice(0, 5).map((m) => `• ${esc(m.skill)} (${m.occurrences} offres)`));
}
if (s.best_open?.length) {
  lines.push('', '⭐ <b>Meilleures offres encore ouvertes</b>');
  lines.push(...s.best_open.map((j) => `• ${j.score}/100 · ${esc(j.title)} → /offre_${j.id}`));
}

let coach = null;
try { coach = parseLLM($json); } catch (e) { /* le rapport part quand même sans coaching */ }
if (coach) {
  lines.push('', '🧠 <b>Le mot du coach</b>', esc(coach.headline || ''));
  if (coach.wins?.length) lines.push(...coach.wins.map((w) => `👏 ${esc(w)}`));
  if (coach.actions?.length) {
    lines.push('', '🚀 <b>Tes 3 actions de la semaine</b>');
    coach.actions.slice(0, 3).forEach((a, i) => lines.push(`${i + 1}. <b>${esc(a.action)}</b> · ${esc(a.why)}`));
  }
  const sk = coach.skill_of_the_week;
  if (sk?.name) lines.push('', `📚 <b>Compétence de la semaine : ${esc(sk.name)}</b>`, esc(sk.why || ''), `👉 ${esc(sk.how || '')}`);
  if (coach.motivation) lines.push('', `💬 <i>${esc(coach.motivation)}</i>`);
}
const text = fit(lines.join('\n'));
return [{ json: { text, content: text.replace(/<[^>]+>/g, '') } }];
